import { MapContainer, TileLayer, Marker, Popup } from "react-leaflet";
import L from "leaflet";

// Default marker icons don't load correctly from the bundled leaflet package
// under Vite, so point them at the CDN explicitly.
const agentIcon = new L.Icon({
  iconUrl: "https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png",
  shadowUrl: "https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png",
  iconSize: [25, 41],
  iconAnchor: [12, 41],
});

export default function LiveMap({ lat, lng, label = "Delivery agent" }) {
  if (!lat || !lng) {
    return (
      <div className="map-box empty-state" style={{ display: "flex", alignItems: "center", justifyContent: "center" }}>
        Waiting for agent's live location…
      </div>
    );
  }

  return (
    <div className="map-box">
      <MapContainer center={[lat, lng]} zoom={15} style={{ height: "100%", width: "100%" }}>
        <TileLayer
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
          attribution='&copy; OpenStreetMap contributors'
        />
        <Marker position={[lat, lng]} icon={agentIcon}>
          <Popup>{label}</Popup>
        </Marker>
      </MapContainer>
    </div>
  );
}
